add_triplet(rows, 'மும்பை இந்தியாவின் தலைநகரம்.', 'புதுடெல்லி இந்தியாவின் தலைநகரம், மும்பை அல்ல.', 'மும்பை இந்தியாவின் நிதி மையமாக அறியப்படுகிறது.', 'மும்பை மகாராஷ்டிராவின் தலைநகரம்.', 'ta', 'https://knowindia.india.gov.in/', 'ta_mumbai_false')
add_triplet(rows, 'சென்னை தமிழ்நாட்டின் தலைநகரம்.', 'சென்னை தமிழ்நாட்டின் தலைநகரம்.', 'தமிழ்நாடு தென் இந்தியாவின் ஒரு மாநிலம்.', 'சென்னை துறைமுகம் மற்றும் தகவல் தொழில்நுட்பத்திற்காகவும் அறியப்படுகிறது.', 'ta', 'https://www.britannica.com/place/Tamil-Nadu', 'ta_chennai_true')
add_triplet(rows, 'பெங்களூரு கர்நாடகத்தின் தலைநகரம் அல்ல.', 'பெங்களூரு கர்நாடகத்தின் தலைநகரமாகும்.', 'பெங்களூரு தகவல் தொழில்நுட்ப மையமாக அறியப்படுகிறது.', 'கர்நாடகம் தென் இந்தியாவின் ஒரு மாநிலம்.', 'ta', 'https://www.britannica.com/place/Karnataka-state-India', 'ta_bengaluru_falseclaim')
add_triplet(rows, 'இந்திய விண்வெளி ஆராய்ச்சி நிறுவனம் பொதுவாக இஸ்ரோ என அழைக்கப்படுகிறது.', 'இந்திய விண்வெளி ஆராய்ச்சி நிறுவனம் (ISRO) இந்தியாவின் விண்வெளி நிறுவனம் ஆகும்.', 'இந்த நிறுவனம் விண்வெளி அறிவியல் மற்றும் தொழில்நுட்ப துறையில் செயல்படுகிறது.', 'இஸ்ரோ பல செயற்கைக்கோள்கள் மற்றும் விண்வெளி முயற்சிகளை நடத்துகிறது.', 'ta', 'https://www.isro.gov.in/profile.html', 'ta_isro_true')
add_triplet(rows, 'இந்தியத் தேர்தல் ஆணையம் ஒரு தனியார் நிறுவனம்.', 'இந்தியத் தேர்தல் ஆணையம் அரசியலமைப்பின் கீழ் இயங்கும் தன்னாட்சி நிறுவனம், தனியார் நிறுவனம் அல்ல.', 'இது தேர்தல் செயல்முறைகளை கண்காணிக்கிறது.', 'இது நாடாளுமன்றம் மற்றும் மாநில சட்டமன்றத் தேர்தல்களை மேற்பார்வை செய்கிறது.', 'ta', 'https://eci.gov.in/', 'ta_eci_false')
add_triplet(rows, 'இந்திய தேசியக்கொடி மூவர்ணக் கொடி.', 'இந்திய தேசியக்கொடி கேசரி, வெள்ளை, பச்சை நிறங்களைக் கொண்ட மூவர்ணக் கொடி.', 'கொடியின் நடுவில் அசோக சக்கரம் உள்ளது.', 'தேசியக்கொடி இந்தியாவின் முக்கிய தேசியச் சின்னமாகும்.', 'ta', 'https://knowindia.india.gov.in/my-india-my-pride/national-flag.php', 'ta_flag_true')
add_triplet(rows, 'செவ்வாய்க்கு இரண்டு நிலவுகள் உள்ளன.', 'செவ்வாய்க்கு போபோஸ் மற்றும் டீமோஸ் என்ற இரண்டு நிலவுகள் உள்ளன.', 'செவ்வாய் சூரியனில் இருந்து நான்காவது கிரகமாகும்.', 'செவ்வாய் சிவப்பு கிரகம் என அழைக்கப்படுகிறது.', 'ta', 'https://science.nasa.gov/mars/moons/', 'ta_mars_true')
add_triplet(rows, 'மனிதர்கள் உபகரணங்கள் இன்றி விண்வெளியில் சுவாசிக்க முடியும்.', 'மனிதர்கள் விண்வெளியின் வெற்றிடத்தில் ஸ்பேஸ்சூட் அல்லது உயிர் ஆதரவு இல்லாமல் சுவாசிக்க முடியாது.', 'விண்வெளி வீரர்கள் சிறப்பு உடைகள் அணிவார்கள்.', 'உயிர் ஆதரவு அமைப்புகள் விண்வெளிப் பயணங்களில் அத்தியாவசியமானவை.', 'ta', 'https://www.nasa.gov/humans-in-space/spacesuits/', 'ta_space_false')
add_triplet(rows, 'வியாழன் சூரியக் குடும்பத்தின் மிகப்பெரிய கிரகம்.', 'வியாழன் சூரியக் குடும்பத்தின் மிகப்பெரிய கிரகம்.', 'வியாழன் ஒரு வாயு மிகாக் கிரகம்.', 'வியாழனுக்கு பல இயற்கைக் கோள்கள் உள்ளன.', 'ta', 'https://science.nasa.gov/jupiter/jupiter-facts/', 'ta_jupiter_true')
add_triplet(rows, 'சுக்கிரன் சூரியனுக்கு மிக அருகிலுள்ள கிரகம்.', 'புதன் சூரியனுக்கு மிக அருகிலுள்ள கிரகம், சுக்கிரன் அல்ல.', 'சுக்கிரன் அளவில் பூமிக்குச் சமமானதாகக் கருதப்படுகிறது.', 'சுக்கிரன் பெரும்பாலான கிரகங்களுக்கு எதிர்திசையில் சுழல்கிறது.', 'ta', 'https://science.nasa.gov/mercury/facts/', 'ta_venus_false')
add_triplet(rows, 'நிஃப்ட் சென்னை 6 மற்றும் 7 மார்ச் 2026 அன்று பொக்கிஷம் கைவினைப் பொருள் கண்காட்சியை நடத்தியது.', 'நிஃப்ட் சென்னை 2026 மார்ச் 6 மற்றும் 7 ஆம் தேதிகளில் பொக்கிஷம் கைவினைப் பொருள் கண்காட்சியை நடத்தியது.', 'இந்தக் கண்காட்சி தமிழ்நாட்டின் கைவினை மற்றும் கைமுறை நெசவு மரபை முன்னிறுத்தியது.', 'இந்த நிகழ்ச்சி சென்னையில் நடைபெற்றது.', 'ta', 'https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2236087&lang=2&reg=3', 'ta_nift_true')

# Kannada
add_triplet(rows, 'ನವದೆಹಲಿ ಭಾರತದ ರಾಜಧಾನಿ.', 'ನವದೆಹಲಿ ಭಾರತದ ರಾಜಧಾನಿ.', 'ಭಾರತದಲ್ಲಿ ಮುಂಬೈ ಮತ್ತು ಕೊಲ್ಕತ್ತಾ போன்ற ದೊಡ್ಡ ನಗರಗಳಿವೆ.', 'ನವದೆಹಲಿ ದೇಶದ ಆಡಳಿತ ಕೇಂದ್ರವಾಗಿದೆ.', 'kn', 'https://knowindia.india.gov.in/', 'kn_delhi_true')
add_triplet(rows, 'ಮುಂಬೈ ಭಾರತದ ರಾಜಧಾನಿ.', 'ನವದೆಹಲಿ ಭಾರತದ ರಾಜಧಾನಿ, ಮುಂಬೈ ಅಲ್ಲ.', 'ಮುಂಬೈ ಭಾರತ ದೇಶದ ಆರ್ಥಿಕ ಕೇಂದ್ರವೆಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ.', 'ಮುಂಬೈ ಮಹಾರಾಷ್ಟ್ರದ ರಾಜಧಾನಿ.', 'kn', 'https://knowindia.india.gov.in/', 'kn_mumbai_false')
add_triplet(rows, 'ಬೆಂಗಳೂರು ಕರ್ನಾಟಕದ ರಾಜಧಾನಿ.', 'ಬೆಂಗಳೂರು ಕರ್ನಾಟಕದ ರಾಜಧಾನಿಯಾಗಿದೆ.', 'ಕರ್ನಾಟಕ ದಕ್ಷಿಣ ಭಾರತದ ಒಂದು ರಾಜ್ಯವಾಗಿದೆ.', 'ಬೆಂಗಳೂರು ಮಾಹಿತಿ ತಂತ್ರಜ್ಞಾನ ಕೇಂದ್ರವಾಗಿ ಪ್ರಸಿದ್ಧವಾಗಿದೆ.', 'kn', 'https://www.britannica.com/place/Karnataka-state-India', 'kn_bengaluru_true')
add_triplet(rows, 'ಚೆನ್ನೈ ಕರ್ನಾಟಕದ ರಾಜಧಾನಿ.', 'ಬೆಂಗಳೂರು ಕರ್ನಾಟಕದ ರಾಜಧಾನಿ, ಚೆನ್ನೈ ಅಲ್ಲ.', 'ಚೆನ್ನೈ ತಮಿಳುನಾಡಿನ ರಾಜಧಾನಿಯಾಗಿದೆ.', 'ಕರ್ನಾಟಕ ದಕ್ಷಿಣ ಭಾರತದ ಒಂದು ರಾಜ್ಯವಾಗಿದೆ.', 'kn', 'https://www.britannica.com/place/Karnataka-state-India', 'kn_chennai_false')
add_triplet(rows, 'ಭಾರತೀಯ ಅಂತರಿಕ್ಷ ಸಂಶೋಧನಾ ಸಂಸ್ಥೆಯನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಇಸ್ರೋ ಎಂದು ಕರೆಯುತ್ತಾರೆ.', 'ಭಾರತೀಯ ಅಂತರಿಕ್ಷ ಸಂಶೋಧನಾ ಸಂಸ್ಥೆ (ISRO) ಭಾರತದ ಅಂತರಿಕ್ಷ ಸಂಸ್ಥೆಯಾಗಿದೆ.', 'ಈ ಸಂಸ್ಥೆ ಅಂತರಿಕ್ಷ ವಿಜ್ಞಾನ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ಕ್ಷೇತ್ರದಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.', 'ಇಸ್ರೋ ಅನೇಕ ಉಪಗ್ರಹ ಹಾಗೂ ಮಿಷನ್‌ಗಳನ್ನು ನಡೆಸುತ್ತದೆ.', 'kn', 'https://www.isro.gov.in/profile.html', 'kn_isro_true')
add_triplet(rows, 'ಭಾರತ ಚುನಾವಣಾ ಆಯೋಗವು ಖಾಸಗಿ ಕಂಪನಿ.', 'ಭಾರತ ಚುನಾವಣಾ ಆಯೋಗವು ಸಂವಿಧಾನಬದ್ಧ ಸ್ವಾಯತ್ತ ಸಂಸ್ಥೆ, ಖಾಸಗಿ ಕಂಪನಿ ಅಲ್ಲ.', 'ಇದು ಚುನಾವಣಾ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುತ್ತದೆ.', 'ಇದು ಲೋಕಸಭೆ ಹಾಗೂ ವಿಧಾನಸಭಾ ಚುನಾವಣೆಗಳನ್ನು ನಡೆಸುತ್ತದೆ.', 'kn', 'https://eci.gov.in/', 'kn_eci_false')
add_triplet(rows, 'ಭಾರತದ ರಾಷ್ಟ್ರೀಯ ಧ್ವಜ ತ್ರಿವರ್ಣ ಧ್ವಜವಾಗಿದೆ.', 'ಭಾರತದ ರಾಷ್ಟ್ರೀಯ ಧ್ವಜ ಕೇಸರಿ, ಬಿಳಿ ಮತ್ತು ಹಸಿರು ಬಣ್ಣಗಳಿರುವ ತ್ರಿವರ್ಣ ಧ್ವಜವಾಗಿದೆ.', 'ಧ್ವಜದ ಮಧ್ಯದಲ್ಲಿ ಅಶೋಕ ಚಕ್ರವಿದೆ.', 'ರಾಷ್ಟ್ರೀಯ ಧ್ವಜವು ಭಾರತದ ಪ್ರಮುಖ ಪ್ರತೀಕವಾಗಿದೆ.', 'kn', 'https://knowindia.india.gov.in/my-india-my-pride/national-flag.php', 'kn_flag_true')
add_triplet(rows, 'ಮಂಗಳ ಗ್ರಹಕ್ಕೆ ಎರಡು ಉಪಗ್ರಹಗಳಿವೆ.', 'ಮಂಗಳ ಗ್ರಹಕ್ಕೆ ಫೋಬೋಸ್ ಮತ್ತು ಡೀಮೋಸ್ ಎಂಬ ಎರಡು ಉಪಗ್ರಹಗಳಿವೆ.', 'ಮಂಗಳ ಸೂರ್ಯನಿಂದ ನಾಲ್ಕನೇ ಗ್ರಹವಾಗಿದೆ.', 'ಮಂಗಳವನ್ನು ಕೆಂಪು ಗ್ರಹ ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ.', 'kn', 'https://science.nasa.gov/mars/moons/', 'kn_mars_true')
add_triplet(rows, 'ಮಾನವರು ಉಪಕರಣಗಳಿಲ್ಲದೆ ಅಂತರಿಕ್ಷದಲ್ಲಿ ಉಸಿರಾಡಬಹುದು.', 'ಮಾನವರು ಸ್ಪೇಸ್‌ಸೂಟ್ ಅಥವಾ ಜೀವಾಧಾರ ಉಪಕರಣಗಳಿಲ್ಲದೆ ಅಂತರಿಕ್ಷದಲ್ಲಿ ಉಸಿರಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.', 'ಅಂತರಿಕ್ಷ ಯಾತ್ರಿಗಳು ವಿಶೇಷ ಉಡುಪುಗಳನ್ನು ಧರಿಸುತ್ತಾರೆ.', 'ಜೀವಾಧಾರ ವ್ಯವಸ್ಥೆಗಳು ಅಂತರಿಕ್ಷ ಮಿಷನ್‌ಗಳಲ್ಲಿ ಅಗತ್ಯವಾಗಿವೆ.', 'kn', 'https://www.nasa.gov/humans-in-space/spacesuits/', 'kn_space_false')
add_triplet(rows, 'ಗುರು ಗ್ರಹವು ಸೌರಮಂಡಲದ ಅತಿ ದೊಡ್ಡ ಗ್ರಹವಾಗಿದೆ.', 'ಗುರು ಗ್ರಹವು ಸೌರಮಂಡಲದ ಅತಿ ದೊಡ್ಡ ಗ್ರಹವಾಗಿದೆ.', 'ಗುರು ಒಂದು ಅನಿಲ ಮಹಾಗ್ರಹವಾಗಿದೆ.', 'ಗುರು ಗ್ರಹಕ್ಕೆ ಅನೇಕ ಉಪಗ್ರಹಗಳಿವೆ.', 'kn', 'https://science.nasa.gov/jupiter/jupiter-facts/', 'kn_jupiter_true')
add_triplet(rows, 'ಶುಕ್ರ ಸೂರ್ಯನಿಗೆ ಅತ್ಯಂತ ಸಮೀಪದ ಗ್ರಹವಾಗಿದೆ.', 'ಬುಧ ಸೂರ್ಯನಿಗೆ ಅತ್ಯಂತ ಸಮೀಪದ ಗ್ರಹ, ಶುಕ್ರ ಅಲ್ಲ.', 'ಶುಕ್ರವನ್ನು ಭೂಮಿಗೆ ಸಮೀಪದ ಗಾತ್ರದ ಗ್ರಹ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ.', 'ಶುಕ್ರ ಬಹುತೇಕ ಗ್ರಹಗಳಿಗೆ ವಿರುದ್ಧ ದಿಕ್ಕಿನಲ್ಲಿ ಭ್ರಮಣ ಮಾಡುತ್ತದೆ.', 'kn', 'https://science.nasa.gov/mercury/facts/', 'kn_venus_false')
add_triplet(rows, 'ಸಿಐಎಸ್ಎಫ್‌ನ ಸ್ಥಾಪನಾ ದಿನದ ಅಂಗವಾಗಿ ಅಮಿತ್ ಶಾ 10 ಮಾರ್ಚ್ 2026ರಂದು ಸಿಬ್ಬಂದಿಗೆ ಶುಭಾಶಯ ಕೋರಿದರು.', 'ಕೇಂದ್ರೀಯ ಗೃಹ ಸಚಿವ ಅಮಿತ್ ಶಾ 10 ಮಾರ್ಚ್ 2026ರಂದು CISF ಸಿಬ್ಬಂದಿಗೆ ಸ್ಥಾಪನಾ ದಿನದ ಶುಭಾಶಯ ಕೋರಿದರು.', 'ಅವರು ಹುತಾತ್ಮರಿಗೆ ನಮನ ಸಲ್ಲಿಸಿದರು.', 'ಅವರು ಸಿಬ್ಬಂದಿಯ ಸೇವಾಭಾವವನ್ನು ಪ್ರಶಂಸಿಸಿದರು.', 'kn', 'https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2237333&lang=1&reg=3', 'kn_cisf_true')

# Malayalam
add_triplet(rows, 'ന്യൂഡൽഹി ഇന്ത്യയുടെ തലസ്ഥാനമാണ്.', 'ന്യൂഡൽഹി ഇന്ത്യയുടെ തലസ്ഥാനമാണ്.', 'ഇന്ത്യയിൽ മുംബൈയും കൊൽക്കത്തയും പോലുള്ള വലിയ നഗരങ്ങൾ ഉണ്ട്.', 'ന്യൂഡൽഹി രാജ്യത്തിന്റെ ഭരണകേന്ദ്രമാണ്.', 'ml', 'https://knowindia.india.gov.in/', 'ml_delhi_true')
add_triplet(rows, 'മുംബൈ ഇന്ത്യയുടെ തലസ്ഥാനമാണ്.', 'ന്യൂഡൽഹി ഇന്ത്യയുടെ തലസ്ഥാനമാണ്, മുംബൈ അല്ല.', 'മുംബൈ ഇന്ത്യയുടെ സാമ്പത്തിക കേന്ദ്രമായി അറിയപ്പെടുന്നു.', 'മുംബൈ മഹാരാഷ്ട്രയുടെ തലസ്ഥാനമാണ്.', 'ml', 'https://knowindia.india.gov.in/', 'ml_mumbai_false')
add_triplet(rows, 'തിരുവനന്തപുരം കേരളത്തിന്റെ തലസ്ഥാനമാണ്.', 'തിരുവനന്തപുരം കേരളത്തിന്റെ തലസ്ഥാനമാണ്.', 'കേരളം ഇന്ത്യയുടെ തെക്കൻ ഭാഗത്തുള്ള ഒരു സംസ്ഥാനമാണ്.', 'തിരുവനന്തപുരം കേരളത്തിന്റെ ഭരണനഗരമാണ്.', 'ml', 'https://www.britannica.com/place/Kerala', 'ml_trivandrum_true')
add_triplet(rows, 'കൊച്ചി കേരളത്തിന്റെ തലസ്ഥാനമാണ്.', 'തിരുവനന്തപുരം കേരളത്തിന്റെ തലസ്ഥാനമാണ്, കൊച്ചി അല്ല.', 'കൊച്ചി കേരളത്തിലെ ഒരു പ്രധാന നഗരമാണ്.', 'കേരളത്തിന് അറബിക്കടൽ തീരമുണ്ട്.', 'ml', 'https://www.britannica.com/place/Kerala', 'ml_kochi_false')
add_triplet(rows, 'ഇന്ത്യൻ ബഹിരാകാശ ഗവേഷണ സംഘടനയെ സാധാരണയായി ഇസ്രോ എന്ന് വിളിക്കുന്നു.', 'ഇന്ത്യൻ ബഹിരാകാശ ഗവേഷണ സംഘടന (ISRO) ഇന്ത്യയുടെ ബഹിരാകാശ ഏജൻസിയാണ്.', 'ഈ സ്ഥാപനം ബഹിരാകാശ ശാസ്ത്രത്തിനും സാങ്കേതിക വിദ്യയ്ക്കുമായി പ്രവർത്തിക്കുന്നു.', 'ഇസ്രോ നിരവധി ഉപഗ്രഹങ്ങളും ദൗത്യങ്ങളും നടത്തുന്നു.', 'ml', 'https://www.isro.gov.in/profile.html', 'ml_isro_true')
add_triplet(rows, 'ഇന്ത്യൻ തെരഞ്ഞെടുപ്പ് കമ്മീഷൻ ഒരു സ്വകാര്യ കമ്പനിയാണ്.', 'ഇന്ത്യൻ തെരഞ്ഞെടുപ്പ് കമ്മീഷൻ സ്വതന്ത്രമായ ഭരണഘടനാ സ്ഥാപനമാണ്, സ്വകാര്യ കമ്പനി അല്ല.', 'ഇത് തിരഞ്ഞെടുപ്പ് നടപടിക്രമങ്ങളെ മേൽനോട്ടം വഹിക്കുന്നു.', 'ഇത് പാർലമെന്റിന്റെയും സംസ്ഥാന നിയമസഭകളുടെയും തിരഞ്ഞെടുപ്പുകൾ നിയന്ത്രിക്കുന്നു.', 'ml', 'https://eci.gov.in/', 'ml_eci_false')
add_triplet(rows, 'ഇന്ത്യയുടെ ദേശീയപതാക ത്രിവർണ്ണ പതാകയാണ്.', 'ഇന്ത്യയുടെ ദേശീയപതാക കേശരി, വെള്ള, പച്ച നിറങ്ങളുള്ള ത്രിവർണ്ണ പതാകയാണ്.', 'പതാകയുടെ നടുവിൽ അശോകചക്രം സ്ഥിതിചെയ്യുന്നു.', 'ദേശീയപതാക ഇന്ത്യയുടെ പ്രധാന ദേശീയചിഹ്നമാണ്.', 'ml', 'https://knowindia.india.gov.in/my-india-my-pride/national-flag.php', 'ml_flag_true')
add_triplet(rows, 'ചൊവ്വയ്ക്ക് രണ്ട് ഉപഗ്രഹങ്ങളുണ്ട്.', 'ചൊവ്വയ്ക്ക് ഫോബോസ്, ഡീമോസ് എന്നീ രണ്ട് ഉപഗ്രഹങ്ങളുണ്ട്.', 'ചൊവ്വ സൂര്യനിൽ നിന്ന് നാലാമത്തെ ഗ്രഹമാണ്.', 'ചൊവ്വയെ ചുവന്ന ഗ്രഹം എന്ന് വിളിക്കാറുണ്ട്.', 'ml', 'https://science.nasa.gov/mars/moons/', 'ml_mars_true')
add_triplet(rows, 'മനുഷ്യർ ഉപകരണങ്ങളില്ലാതെ ബഹിരാകാശത്തിൽ ശ്വസിക്കാൻ കഴിയും.', 'മനുഷ്യർ സ്പേസ്‌സ്യൂട്ടോ ജീവൻ രക്ഷാ സംവിധാനമോ ഇല്ലാതെ ബഹിരാകാശത്തിൽ ശ്വസിക്കാൻ കഴിയില്ല.', 'ബഹിരാകാശയാത്രികർ പ്രത്യേക വസ്ത്രം ധരിക്കുന്നു.', 'ജീവൻ രക്ഷാ സംവിധാനങ്ങൾ ബഹിരാകാശ യാത്രയിൽ അനിവാര്യമാണ്.', 'ml', 'https://www.nasa.gov/humans-in-space/spacesuits/', 'ml_space_false')
add_triplet(rows, 'വ്യാഴം സൗരയൂഥത്തിലെ ഏറ്റവും വലിയ ഗ്രഹമാണ്.', 'വ്യാഴം സൗരയൂഥത്തിലെ ഏറ്റവും വലിയ ഗ്രഹമാണ്.', 'വ്യാഴം ഒരു വാതക മഹാഗ്രഹമാണ്.', 'വ്യാഴത്തിന് അനവധി ഉപഗ്രഹങ്ങളുണ്ട്.', 'ml', 'https://science.nasa.gov/jupiter/jupiter-facts/', 'ml_jupiter_true')
add_triplet(rows, 'ശുക്രൻ സൂര്യനോട് ഏറ്റവും അടുത്ത ഗ്രഹമാണ്.', 'ബുധൻ സൂര്യനോട് ഏറ്റവും അടുത്ത ഗ്രഹമാണ്, ശുക്രൻ അല്ല.', 'ശുക്രനെ ഭൂമിയോടടുത്ത വലിപ്പമുള്ള ഗ്രഹമായി കണക്കാക്കുന്നു.', 'ശുക്രൻ ഭൂരിഭാഗം ഗ്രഹങ്ങൾക്കും വിപരീത ദിശയിൽ ഭ്രമണം ചെയ്യുന്നു.', 'ml', 'https://science.nasa.gov/mercury/facts/', 'ml_venus_false')
add_triplet(rows, 'കേരളത്തിലെ സ്ത്രീകൾക്കും അമ്മമാർക്കും അട്ടുകാൽ പൊങ്കാലയുടെ ആശംസകൾ അമിത് ഷാ 2026 മാർച്ച് 3ന് നേർന്നു.', 'കേന്ദ്ര ആഭ്യന്തരമന്ത്രി അമിത് ഷാ 2026 മാർച്ച് 3ന് അട്ടുകാൽ പൊങ്കാലയുടെ അവസരത്തിൽ കേരളത്തിലെ സ്ത്രീകൾക്കും അമ്മമാർക്കും ആശംസകൾ നേർന്നു.', 'അട്ടുകാൽ അമ്മയുടെ അനുഗ്രഹം എല്ലാവരുടെയും ജീവിതം സമൃദ്ധിയാൽ നിറക്കട്ടെയെന്ന് അദ്ദേഹം ആശംസിച്ചു.', 'ഈ സന്ദേശം അട്ടുകാൽ പൊങ്കാലയുമായി ബന്ധപ്പെട്ടിരുന്നു.', 'ml', 'https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2234974', 'ml_attukal_true')

OUT.parent.mkdir(parents=True, exist_ok=True)
with OUT.open('w', encoding='utf-8') as handle:
    for row in rows:
        handle.write(json.dumps(row, ensure_ascii=False) + '\n')

print(f'Wrote {len(rows)} rows to {OUT}')
